"""Parse CSV text into a list of row dicts."""


def _split_line(line: str, delimiter: str) -> list[str]:
    fields: list[str] = []
    i, n = 0, len(line)
    while True:
        if i < n and line[i] == '"':
            # Quoted field: runs to the next unpaired quote.
            i += 1
            buf = []
            while True:
                if i >= n:
                    raise ValueError("unterminated quoted field")
                ch = line[i]
                if ch == '"':
                    if line[i + 1:i + 2] == '"':
                        buf.append('"')
                        i += 2
                        continue
                    i += 1
                    break
                buf.append(ch)
                i += 1
            if i < n and not line.startswith(delimiter, i):
                raise ValueError("unexpected text after closing quote")
            fields.append("".join(buf))
        else:
            j = line.find(delimiter, i)
            if j == -1:
                j = n
            fields.append(line[i:j])
            i = j
        if i >= n:
            return fields
        i += len(delimiter)  # skip delimiter; a trailing one yields an empty last field
        if i >= n:
            fields.append("")
            return fields


def parse_csv(text: str, delimiter: str = ",") -> list[dict[str, str]]:
    """Parse ``text`` and return one dict per data row, keyed by the header names."""
    if not delimiter or delimiter == '"' or "\n" in delimiter or "\r" in delimiter:
        raise ValueError("invalid delimiter")
    rows = []
    for line in text.split("\n"):
        if line.endswith("\r"):
            line = line[:-1]
        if not line.strip():
            continue
        rows.append(_split_line(line, delimiter))
    if not rows:
        return []
    header, *data = rows
    result = []
    for row in data:
        if len(row) != len(header):
            raise ValueError(
                f"expected {len(header)} fields, got {len(row)}: {row!r}"
            )
        result.append(dict(zip(header, row)))
    return result
